package com.projectdark.mobile;
import android.content.Context;import android.graphics.*;import com.projectdark.mobile.world.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.nio.file.Files;import java.nio.file.Path;import java.util.*;import java.lang.reflect.Method;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class CoastRefinementV158Test {
 Context c;Path out=Path.of("build/reports/coast-v158");
 @Before public void setup(){c=RuntimeEnvironment.getApplication();for(String n:new String[]{"project_dark_f5m_v1","project_dark_skill_book_v1","project_dark_skill_test_v1"})c.getSharedPreferences(n,0).edit().clear().commit();F5mSaveStore.install(c);}
 void save(Bitmap b,String n)throws Exception{Files.createDirectories(out);try(java.io.OutputStream s=Files.newOutputStream(out.resolve(n+".png"))){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,s));}}
 void change(GameView v,String id)throws Exception{Method m=GameView.class.getDeclaredMethod("changeCampaignMap",String.class,boolean.class);m.setAccessible(true);m.invoke(v,id,false);}
 String[][] routes(){return new String[][]{AbelCoastGeometry.ROUTE,RucesionCoastGeometry.ROUTE};}
 @Test public void squareMapsRetainAllSpeciesAndFullPopulationsWithLargeReachableRocks(){Set<String> abel=new HashSet<>(),ruc=new HashSet<>();for(String[] route:routes()){assertEquals(5,route.length);for(int i=0;i<route.length;i++){String map=route[i];PoteCampaignMapDef d=PoteCampaignMapDef.forId(map);assertEquals(d.maxX,d.maxY,.01f);assertTrue(i==0?d.maxX<=800:d.maxX<=2560);String label=CampaignWorld.title(map);assertTrue(i==0?label.endsWith("대기방"):i==4?label.endsWith("보스방"):label.endsWith(" "+i));RuntimeState s=new RuntimeState();s.enterCampaignMap(map,false);assertEquals(i==0?0:AbelCoastGeometry.contains(map)?i==1?65:i==2?86:97:i==4?8:i==1?65:86,s.monsters().size());for(RuntimeState.Monster m:s.monsters()){assertFalse(d.terrainBlocked(m.x,m.y,18));(AbelCoastGeometry.contains(map)?abel:ruc).add(m.campaignRewardProfileId);}Set<String> tiles=new HashSet<>();for(WorldMoveTargetController.TileCenter t:CampaignWorld.connectedTiles(map))tiles.add(t.x+":"+t.y);for(WorldMoveTargetController.TileCenter t:new WorldMoveTargetController.TileCenter[]{CampaignWorld.forward(map),CampaignWorld.backward(map),CampaignWorld.arrival(map,false),CampaignWorld.arrival(map,true)})assertTrue(tiles.contains(t.x+":"+t.y));if(i==3){List<CoastalHuntLayout.Prop> p=CoastalHuntLayout.props(i,RucesionCoastGeometry.contains(map));assertTrue(p.stream().anyMatch(a->a.solid&&a.asset.startsWith("reef")&&a.scale>=2));}}}assertEquals(new HashSet<>(AbelCoastMonsters.ALL),abel);assertEquals(new HashSet<>(RucesionCoastMonsters.ALL),ruc);}
 @Test public void arrivalPortalIsImmediatelyVisibleAndActualWalkEntersHuntingMap()throws Exception{for(String[] route:routes()){setup();GameView v=new GameView(c);v.layout(0,0,960,540);TownInteriorTest.call(v,"enterPoteField");v.setSkillTestMode(true);change(v,route[0]);RuntimeState s=TownInteriorTest.field(v,"state");WorldRuntimeAdapter w=TownInteriorTest.field(v,"poteFieldAdapter");WorldMoveTargetController.TileCenter t=CampaignWorld.forward(route[0]);WorldCameraTransform.Point p=w.worldToScreen(t.x,t.y);assertTrue("arrival portal inside visible play area",p.x>100&&p.x<900&&p.y>200&&p.y<380);assertTrue(Math.hypot(t.x-s.player().x,t.y-s.player().y)<400);Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));save(b,route[0]+"-arrival-portal");assertTrue(CampaignNavigationTest.walk(w,w.requestGroundWorld(t.x,t.y)));TownInteriorTest.tick(v,1);assertEquals(route[1],s.currentMapId());w=TownInteriorTest.field(v,"poteFieldAdapter");t=CampaignWorld.backward(route[1]);assertTrue(CampaignNavigationTest.walk(w,w.requestGroundWorld(t.x,t.y)));TownInteriorTest.tick(v,1);assertEquals(route[0],s.currentMapId());}}
 @Test public void legacyAbelDuplicateMapRestoresToHuntOneWithoutLostRewards()throws Exception{RuntimeState s=new RuntimeState();s.rpg().grantAdaptedReward(5500,123);s.enterCampaignMap("MAP_ABEL_COAST_1B",false);assertEquals(AbelCoastGeometry.ROUTE[1],s.currentMapId());assertTrue(CampaignWorld.contains("MAP_ABEL_COAST_1B"));assertEquals(AbelCoastGeometry.ROUTE[2],CampaignWorld.next("MAP_ABEL_COAST_1B"));F5mSaveStore.bindRuntime(s,F5mAdaptedPrologueQuest.openingFixture(),new GrowthQuest2());assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(c);GameView v=new GameView(c);RuntimeState restored=TownInteriorTest.field(v,"state");assertEquals(s.currentMapId(),restored.currentMapId());assertEquals(s.rpg().gold(),restored.rpg().gold());assertFalse(restored.blocked(restored.player().x,restored.player().y));}
 Rect bounds(Bitmap b){int l=b.getWidth(),t=b.getHeight(),r=0,d=0;for(int y=0;y<b.getHeight();y++)for(int x=0;x<b.getWidth();x++)if(Color.alpha(b.getPixel(x,y))>16){l=Math.min(l,x);r=Math.max(r,x+1);t=Math.min(t,y);d=Math.max(d,y+1);}return new Rect(l,t,r,d);}
 @Test public void sourceNamedRaysBluePaletteAndNativePlayerRelativeSilhouettesAreReviewed()throws Exception{PoteFieldRenderer renderer=new PoteFieldRenderer();CharacterRenderer player=new CharacterRenderer(c);RuntimeState s=new RuntimeState();CharacterVisualBinding v=CharacterVisualBinding.from(s.rpg());Bitmap p=Bitmap.createBitmap(200,200,Bitmap.Config.ARGB_8888);player.draw(new Canvas(p),new CharacterRenderer.Pose(100,160,CharacterRenderer.Direction.SW,CharacterRenderer.State.IDLE,0,0,1,false,v.equipmentVisualRef(),null,CharacterRenderer.ASSET_STATUS,CharacterRenderer.EffectFamily.NONE));Rect pb=bounds(p);assertTrue(pb.height()>25);org.json.JSONObject report=new org.json.JSONObject();Bitmap grid=Bitmap.createBitmap(1100,600,Bitmap.Config.ARGB_8888);Canvas g=new Canvas(grid);g.drawColor(0xffb9a070);int i=0;
  for(String id:RucesionCoastMonsters.ALL){Bitmap m=Bitmap.createBitmap(250,250,Bitmap.Config.ARGB_8888);renderer.drawMonsterTestPose(new Canvas(m),id,"idle",CharacterRenderer.Direction.SW,0,0,125,220);Rect mb=bounds(m);double hr=mb.height()/(double)pb.height(),wr=mb.width()/(double)pb.width();assertTrue(id+" source-scale envelope",hr>.55&&hr<3.7);if(id.endsWith("KOATL"))assertTrue(id+" rays must remain broad",wr>1.8);report.put(id,new org.json.JSONObject().put("heightToEquippedPlayer",hr).put("widthToEquippedPlayer",wr).put("runtimeCanvasHeight",PoteForestMonsterShowcase.bodyHeight(id)));float x=70+i%5*220,y=220+i/5*280;player.draw(g,new CharacterRenderer.Pose(x,y,CharacterRenderer.Direction.SW,CharacterRenderer.State.IDLE,0,0,1,false,v.equipmentVisualRef(),v.weaponVisualRef(),CharacterRenderer.ASSET_STATUS,CharacterRenderer.EffectFamily.NONE));renderer.drawMonsterTestPose(g,id,"idle",CharacterRenderer.Direction.SW,0,0,x+90,y);Paint text=new Paint();text.setTextSize(12);text.setColor(Color.BLACK);g.drawText(RucesionCoastMonsters.name(id),x-30,y+35,text);i++;}
  Bitmap blue=BitmapFactory.decodeStream(c.getAssets().open(PoteForestMonsterShowcase.assetPath("LYK_BLUE_HACON","idle",CharacterRenderer.Direction.SW)));int blues=0,solid=0;for(int y=0;y<blue.getHeight();y++)for(int x=0;x<blue.getWidth();x++){int q=blue.getPixel(x,y);if(Color.alpha(q)>16){solid++;if(Color.blue(q)>Color.red(q)*1.3&&Color.blue(q)>Color.green(q)*1.15)blues++;}}assertTrue("user-confirmed Blue Hacon visibly blue",blues>solid*.35);assertTrue(PoteForestMonsterShowcase.assetPath("LYK_KOATL","idle",CharacterRenderer.Direction.SW).contains("/koatl/"));assertTrue(PoteForestMonsterShowcase.assetPath("LYK_ELECT_KOATL","idle",CharacterRenderer.Direction.SW).contains("/elect_koatl/"));save(grid,"player-and-ten-monsters-native-scale");Files.write(out.resolve("native-scale-ratios.json"),report.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 @Test public void nativeSquareOverviewsShowDifferentReefLayoutsWithoutChangingCacheLimits()throws Exception{PoteFieldRenderer renderer=new PoteFieldRenderer();for(String[] route:routes())for(String map:route){RuntimeState s=new RuntimeState();s.enterCampaignMap(map,false);PoteCampaignMapDef d=PoteCampaignMapDef.forId(map);float sz=d.maxX;WorldRuntimeAdapter w=new WorldRuntimeAdapter(s,sz,sz,d.minX,d.maxX,d.minY,d.maxY,d.navigationTiles(),d.obstacles(),true);w.camera().snapTo(sz*.5f,sz*.5f);renderer.prepareMonsters(s);Bitmap b=Bitmap.createBitmap((int)sz,(int)sz,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);List<PoteFieldRenderer.ActorDraw> actors=new ArrayList<>();for(RuntimeState.Monster m:s.monsters()){WorldCameraTransform.Point at=w.worldToScreen(m.x,m.y);actors.add(new PoteFieldRenderer.ActorDraw(m.x,m.y,PoteForestMonsterShowcase.bodyHeight(m.id),52,()->renderer.drawMonster(c,m,at.x,at.y)));}renderer.drawScene(c,w,actors);assertTrue(((Map<?,?>)ForestPixelCacheTest.field(renderer,"floorChunks")).size()<=32);assertTrue(((Map<?,?>)ForestPixelCacheTest.field(renderer,"hitCache")).size()<=60);for(int k=1;k<4;k++)assertTrue("whole-scene floor is rendered",Color.alpha(b.getPixel((int)(sz*k/4),(int)(sz*.5f)))>240);Bitmap preview=Bitmap.createScaledBitmap(b,800,800,false);save(preview,map+"-square-overview");if(preview!=b)preview.recycle();b.recycle();}}
}
